        }
        foreach (is_array($current['owner_generations'] ?? null) ? $current['owner_generations'] : [] as $owner => $generation) {
            $state['owner_generations'][self::pathName198201((string) $owner)] = self::positiveInt198201($generation, 'owner generation');
        }
        foreach (is_array($current['sources'] ?? null) ? $current['sources'] : [] as $name => $source) {
            if (!is_array($source)) {
                continue;
            }
            $path = self::pathName198201((string) ($source['path'] ?? ''));
            $sourceName = self::sourceName198201((string) $name);
            $state['sources'][$sourceName] = self::sourceState198201(
                self::token198201((string) ($source['handle'] ?? $sourceName), 'handle'),
                $path,
                self::pathName198201((string) ($source['owner'] ?? self::owner198201($path))),
                self::lockLevel198201((string) ($source['lock'] ?? 'none')),
                (bool) ($source['readonly'] ?? false),
                self::nonNegativeInt198201($source['data_version'] ?? 0, 'data version'),
                self::receiptList198201($source['write_receipts'] ?? []),
                self::receiptList198201($source['durable_receipts'] ?? []),
                self::dirtyPageMap198201($source['dirty_pages'] ?? []),
                is_array($source['checkpoints'] ?? null) ? array_values($source['checkpoints']) : [],
                self::nonNegativeInt198201($source['flush_count'] ?? 0, 'flush count'),
                (bool) ($source['closed'] ?? false)
