                continue;
            }

            if ($op['kind'] === 'publish') {
                $pages = self::pageList202205($op['pages'] ?? []);
                $missing = [];
                foreach ($pages as $page) {
                    if (!isset($state['sources'][$source]['prepared_pages'][$page])) {
                        $missing[] = $page;
                    }
                }
                if ($missing !== []) {
                    $events[] = self::event202205('publish_batch', 'missing-prepared-pages', $source, $before, self::summary202205($state), [
                        'missing_pages' => $missing,
