            'next' => self::summary202205($state),
            'events' => $events,
            'dependencies' => [
                'vfs-current-source-durable-receipts-next194-197',
                'vfs-current-source-local-prerequisite-next198-201',
                'vfs-current-source-publish-reader-fence-next202-205',
