    private static function snapshot250253(array &$state, string $source, string $snapshot, array $before): array
    {
        if (!isset($state['sources'][$source]) || $state['sources'][$source]['closed'] === true) {
            return self::event250253('snapshot', 'missing-source', $source, $before, self::summary250253($state), ['snapshot' => $snapshot]);
        }

        $sourceState = $state['sources'][$source];
        $readyReceipt = self::lastReadyReceipt250253($sourceState);
        $publishReceipt = self::lastPublishReceipt250253($sourceState);
        if ($readyReceipt === null || $publishReceipt === null || $sourceState['dirty_pages'] !== []) {
            return self::event250253('snapshot', 'blocked-not-ready', $source, $before, self::summary250253($state), [
                'snapshot' => $snapshot,
                'dirty_count' => count($sourceState['dirty_pages']),
                'ready_token' => $readyReceipt['token'] ?? null,
                'publish_token' => $publishReceipt['token'] ?? null,
            ]);
        }

        $state['snapshots'][$snapshot] = [
            'source' => $source,
            'handle' => $sourceState['handle'],
            'path' => $sourceState['path'],
            'owner' => $sourceState['owner'],
            'data_version' => $sourceState['data_version'],
            'ready_token' => $readyReceipt['token'],
            'publish_token' => $publishReceipt['token'],
            'published_count' => count($sourceState['published']),
            'reuse_lease_count' => count($sourceState['reuse_leases']),
            'receipt_digest' => self::receiptDigest250253($sourceState['published']),
        ];

        return self::event250253('snapshot', 'captured-ready', $source, $before, self::summary250253($state), [
            'snapshot' => $snapshot,
            'ready_token' => $readyReceipt['token'],
            'publish_token' => $publishReceipt['token'],
        ]);
    }

    private static function publish250253(array &$state, string $source, string $snapshot, string $token, array $before): array
    {
        if (!isset($state['sources'][$source]) || $state['sources'][$source]['closed'] === true) {
            return self::event250253('publish', 'missing-source', $source, $before, self::summary250253($state), ['snapshot' => $snapshot, 'token' => $token]);
        }
        if (!isset($state['snapshots'][$snapshot])) {
            return self::event250253('publish', 'missing-snapshot', $source, $before, self::summary250253($state), ['snapshot' => $snapshot, 'token' => $token]);
        }

        $sourceState = $state['sources'][$source];
        $snapshotState = $state['snapshots'][$snapshot];
        $blockers = self::publicationBlockers250253($snapshotState, $sourceState);
        $lease = self::lastReuseLease250253($sourceState, $snapshot);
        if ($lease === null) {
            $blockers[] = 'missing-reuse-lease';
        } elseif (
            $lease['snapshot'] !== $snapshot
            || $lease['data_version'] !== $sourceState['data_version']
            || $lease['published_count'] !== count($sourceState['published'])
            || $lease['receipt_digest'] !== self::receiptDigest250253($sourceState['published'])
        ) {
            $blockers[] = 'stale-reuse-lease';
        }
        if ($blockers !== []) {
            return self::event250253('publish', 'blocked-stale', $source, $before, self::summary250253($state), [
                'snapshot' => $snapshot,
                'token' => $token,
                'blocked_reasons' => $blockers,
            ]);
        }

        $state['sources'][$source]['published'][] = [
            'token' => $token,
            'data_version' => $sourceState['data_version'],
            'published_count' => count($sourceState['published']) + 1,
            'source_snapshot' => $snapshot,
            'reuse_lease' => $lease['token'],
        ];

        return self::event250253('publish', 'published-current-source', $source, $before, self::summary250253($state), [
            'snapshot' => $snapshot,
            'token' => $token,
            'reuse_lease' => $lease['token'],
            'published_count' => count($state['sources'][$source]['published']),
        ]);
    }

    private static function reuse250253(array &$state, string $source, string $snapshot, string $lease, array $before): array
    {
        if (!isset($state['sources'][$source]) || !isset($state['snapshots'][$snapshot])) {
            return self::event250253('reuse', 'missing-source-or-snapshot', $source, $before, self::summary250253($state), ['snapshot' => $snapshot, 'lease' => $lease]);
        }

        $blockers = self::publicationBlockers250253($state['snapshots'][$snapshot], $state['sources'][$source]);
        if ($blockers === []) {
            $state['sources'][$source]['reuse_leases'][] = [
                'token' => $lease,
                'snapshot' => $snapshot,
                'data_version' => $state['sources'][$source]['data_version'],
                'published_count' => count($state['sources'][$source]['published']),
                'receipt_digest' => self::receiptDigest250253($state['sources'][$source]['published']),
            ];
        }

        return self::event250253('reuse', $blockers === [] ? 'leased-current-source' : 'blocked-stale', $source, $before, self::summary250253($state), [
            'snapshot' => $snapshot,
            'lease' => $lease,
            'reuse_lease_count' => count($state['sources'][$source]['reuse_leases']),
            'blocked_reasons' => $blockers,
        ]);
    }

    private static function hydrate250253(mixed $current): array
    {
        $state = ['current_source' => null, 'sources' => [], 'snapshots' => []];
        if (!is_array($current)) {
            return $state;
        }
        foreach (is_array($current['sources'] ?? null) ? $current['sources'] : [] as $name => $source) {
            if (!is_array($source)) {
                continue;
            }
            $sourceName = self::token250253((string) $name, 'source name');
            $state['sources'][$sourceName] = [
                'handle' => self::token250253((string) ($source['handle'] ?? $sourceName), 'handle'),
                'path' => self::path250253((string) ($source['path'] ?? '')),
                'owner' => self::path250253((string) ($source['owner'] ?? $source['path'] ?? '')),
                'closed' => (bool) ($source['closed'] ?? false),
                'data_version' => self::nonNegativeInt250253($source['data_version'] ?? 0, 'data version'),
                'dirty_pages' => self::receiptList250253($source['dirty_pages'] ?? []),
                'ready_receipts' => self::receiptMetadataList250253($source['ready_receipts'] ?? []),
                'published' => self::receiptMetadataList250253($source['published'] ?? []),
                'reuse_leases' => self::reuseLeaseList250253($source['reuse_leases'] ?? []),
            ];
        }
        foreach (is_array($current['snapshots'] ?? null) ? $current['snapshots'] : [] as $name => $snapshot) {
            if (!is_array($snapshot)) {
                continue;
            }
            $state['snapshots'][self::token250253((string) $name, 'snapshot name')] = [
                'source' => self::token250253((string) ($snapshot['source'] ?? 'main'), 'snapshot source'),
                'handle' => self::token250253((string) ($snapshot['handle'] ?? $name), 'snapshot handle'),
                'path' => self::path250253((string) ($snapshot['path'] ?? '')),
                'owner' => self::path250253((string) ($snapshot['owner'] ?? $snapshot['path'] ?? '')),
                'data_version' => self::nonNegativeInt250253($snapshot['data_version'] ?? 0, 'snapshot data version'),
                'ready_token' => self::token250253((string) ($snapshot['ready_token'] ?? 'ready'), 'ready token'),
                'publish_token' => self::token250253((string) ($snapshot['publish_token'] ?? 'publish'), 'publish token'),
                'published_count' => self::nonNegativeInt250253($snapshot['published_count'] ?? 0, 'snapshot published count'),
                'reuse_lease_count' => self::nonNegativeInt250253($snapshot['reuse_lease_count'] ?? 0, 'snapshot reuse lease count'),
                'receipt_digest' => self::token250253((string) ($snapshot['receipt_digest'] ?? 'empty'), 'receipt digest'),
            ];
        }
        if (isset($current['current_source'])) {
            $state['current_source'] = self::token250253((string) $current['current_source'], 'current source');
        }
        return $state;
    }

    private static function operation250253(string|array $operation): array
    {
        if (is_array($operation)) {
            $kind = strtolower(str_replace(['_', '-'], '', (string) ($operation['op'] ?? $operation['kind'] ?? '')));
            return $operation + ['kind' => match ($kind) {
                'capturesnapshot', 'snapshotcapture' => 'snapshot',
                'publishsnapshot', 'publishsource', 'sourcepublish' => 'publish',
                'reusesnapshot', 'snapshotreuse', 'leasereuse', 'reuselease' => 'reuse',
                default => $kind,
            }];
        }

        $trimmed = trim($operation);
        if (preg_match('/^snapshot\s*\(\s*(?<snapshot>[A-Za-z0-9_.:-]+)\s*\)$/', $trimmed, $matches) === 1) {
            return ['kind' => 'snapshot', 'snapshot' => $matches['snapshot']];
        }
        if (preg_match('/^reuse\s*\(\s*(?<snapshot>[A-Za-z0-9_.:-]+)(?:\s*,\s*(?<lease>[A-Za-z0-9_.:-]+))?\s*\)$/', $trimmed, $matches) === 1) {
            return ['kind' => 'reuse', 'snapshot' => $matches['snapshot'], 'lease' => $matches['lease'] ?? null];
        }
        if (preg_match('/^publish\s*\(\s*(?<snapshot>[A-Za-z0-9_.:-]+)\s*,\s*(?<token>[A-Za-z0-9_.:-]+)\s*\)$/', $trimmed, $matches) === 1) {
            return ['kind' => 'publish', 'snapshot' => $matches['snapshot'], 'token' => $matches['token']];
        }
        throw new \InvalidArgumentException('SQLite VFS current-source next250-253 operation is unsupported');
    }

    private static function summary250253(array $state): array
    {
        return [
            'current_source' => $state['current_source'],
            'source_count' => count($state['sources']),
            'snapshot_count' => count($state['snapshots']),
            'sources' => $state['sources'],
            'snapshots' => $state['snapshots'],
        ];
    }

    /** @return list<string> */
    private static function publicationBlockers250253(array $snapshot, array $source): array
    {
        $blockers = [];
        foreach (['handle', 'path', 'owner', 'data_version'] as $key) {
            if ($snapshot[$key] !== $source[$key]) {
                $blockers[] = str_replace('_', '-', $key) . '-changed';
            }
        }
        if ($snapshot['published_count'] !== count($source['published'])) {
            $blockers[] = 'published-count-changed';
        }
        if ($snapshot['receipt_digest'] !== self::receiptDigest250253($source['published'])) {
            $blockers[] = 'publish-receipt-digest-changed';
        }
        if ($source['dirty_pages'] !== []) {
            $blockers[] = 'dirty-pages-present';
        }
        return $blockers;
    }

    private static function sourceFor250253(array $state, mixed $source): string
    {
        if ($source !== null && $source !== '') {
            return self::token250253((string) $source, 'source name');
        }
        if (is_string($state['current_source'])) {
            return $state['current_source'];
        }
        return 'main';
    }

    private static function event250253(string $kind, string $status, string $source, array $before, array $next, array $extra): array
    {
        return ['kind' => $kind, 'status' => $status, 'source' => $source, 'before' => $before, 'next' => $next] + $extra;
    }

    private static function lastReadyReceipt250253(array $source): ?array
    {
        if ($source['ready_receipts'] === []) {
            return null;
        }
        return $source['ready_receipts'][array_key_last($source['ready_receipts'])];
    }

    private static function lastPublishReceipt250253(array $source): ?array
    {
        if ($source['published'] === []) {
            return null;
        }
        return $source['published'][array_key_last($source['published'])];
    }

    private static function lastReuseLease250253(array $source, string $snapshot): ?array
    {
        for ($i = count($source['reuse_leases']) - 1; $i >= 0; --$i) {
            if ($source['reuse_leases'][$i]['snapshot'] === $snapshot) {
                return $source['reuse_leases'][$i];
            }
        }
        return null;
    }

    private static function receiptDigest250253(array $receipts): string
    {
        $tokens = array_map(static fn (array $receipt): string => (string) $receipt['token'], $receipts);
        return $tokens === [] ? 'empty' : hash('sha256', implode('|', $tokens));
    }

    private static function path250253(string $path): string
    {
        $path = trim($path);
        if ($path === '' || str_contains($path, "\0")) {
            throw new \InvalidArgumentException('SQLite VFS current-source next250-253 requires valid paths');
        }
        return $path;
    }

    private static function token250253(string $token, string $label): string
