            throw new \InvalidArgumentException('SQLite VFS current-source next250-253 requires valid ' . $label);
        }
        return $token;
    }

    private static function nonNegativeInt250253(mixed $value, string $label): int
    {
        if (!is_int($value) || $value < 0) {
            throw new \InvalidArgumentException('SQLite VFS current-source next250-253 requires non-negative ' . $label);
        }
        return $value;
    }

