    // Consolidated behavior from next254-257.
/**
     * @param list<array<string, mixed>|string> $operations
     * @param array<string, mixed> $options
     * @return array<string, mixed>
     */
    private static function run254257(array $operations, array $options = []): array
    {
        if ($operations === []) {
            throw new \InvalidArgumentException('SQLite VFS current-source next254-257 requires operations');
        }

        $state = self::hydrate254257($options['current'] ?? []);
        $current = self::summary254257($state);
        $events = [];

        foreach ($operations as $operation) {
            $op = self::operation254257($operation);
            $source = self::sourceFor254257($state, $op['source'] ?? null);
            $before = self::summary254257($state);

            if ($op['kind'] === 'claim') {
                $snapshot = self::token254257((string) ($op['snapshot'] ?? ''), 'snapshot name');
                $ack = self::token254257((string) ($op['ack'] ?? ''), 'reuse acknowledgement');
                $claim = self::token254257((string) ($op['claim'] ?? $snapshot . '-claim'), 'reuse claim');
                $events[] = self::claim254257($state, $source, $snapshot, $ack, $claim, $before);
                continue;
            }

            if ($op['kind'] === 'publish') {
                $snapshot = self::token254257((string) ($op['snapshot'] ?? ''), 'snapshot name');
                $claim = self::token254257((string) ($op['claim'] ?? ''), 'reuse claim');
                $token = self::token254257((string) ($op['token'] ?? 'publish'), 'publish token');
                $events[] = self::publish254257($state, $source, $snapshot, $claim, $token, $before);
                continue;
            }

            throw new \InvalidArgumentException('SQLite VFS current-source next254-257 operation is unsupported');
        }

        return [
            'status' => (string) ($events[array_key_last($events)]['status'] ?? 'ok'),
            'current' => $current,
            'next' => self::summary254257($state),
            'events' => $events,
            'dependencies' => [
                'vfs-current-source-snapshot-reuse-next206-209',
                'vfs-current-source-ready-next214-217',
                'vfs-current-source-reuse-publish-next218-221',
                'vfs-current-source-reuse-lease-publish-next226-229',
                'vfs-current-source-reuse-ack-publish-next234-237',
                'vfs-current-source-snapshot-reuse-publish-next242-245',
                'vfs-current-source-snapshot-reuse-publish-next254-257',
            ],
            'non_overlap' => 'next254-257 follows ready next242-245 and reserves a fresh reuse claim for the already acknowledged current-source snapshot before the next publication; it does not touch active next246-253 files, earlier capture/readiness/lease gates, dirty flushing, VFS locking, WAL checkpointing, or B-tree behavior.',
        ];
    }

    private static function claim254257(array &$state, string $source, string $snapshot, string $ack, string $claim, array $before): array
    {
        if (!isset($state['sources'][$source]) || !isset($state['snapshots'][$snapshot])) {
            return self::event254257('claim', 'missing-source-or-snapshot', $source, $before, self::summary254257($state), [
                'snapshot' => $snapshot,
                'ack' => $ack,
                'claim' => $claim,
            ]);
        }

        $sourceState = $state['sources'][$source];
        $snapshotState = $state['snapshots'][$snapshot];
        $blockers = self::reuseBlockers254257($snapshotState, $sourceState);
        $ackState = self::lastReuseAck254257($sourceState, $snapshot);
        if ($ackState === null || $ackState['receipt'] !== $ack) {
            $blockers[] = 'missing-reuse-ack';
        } elseif (
            $ackState['data_version'] !== $sourceState['data_version']
            || $ackState['published_count'] !== $snapshotState['published_count']
            || $ackState['receipt_digest'] !== $snapshotState['receipt_digest']
        ) {
            $blockers[] = 'stale-reuse-ack';
        }

        if ($blockers === []) {
            $state['sources'][$source]['reuse_claims'][] = [
                'token' => $claim,
                'snapshot' => $snapshot,
                'ack' => $ack,
                'data_version' => $sourceState['data_version'],
                'published_count' => count($sourceState['published']),
                'receipt_digest' => self::receiptDigest254257($sourceState['published']),
