        }

        return self::event254257('claim', $blockers === [] ? 'claimed-reusable-current-source' : 'blocked-stale', $source, $before, self::summary254257($state), [
            'snapshot' => $snapshot,
            'ack' => $ack,
            'claim' => $claim,
            'reuse_claim_count' => count($state['sources'][$source]['reuse_claims'] ?? []),
