            $state['snapshots'][self::token254257((string) $name, 'snapshot name')] = [
                'source' => self::token254257((string) ($snapshot['source'] ?? 'main'), 'snapshot source'),
                'handle' => self::token254257((string) ($snapshot['handle'] ?? $name), 'snapshot handle'),
