            $op = self::operation258265($operation);
            $source = self::sourceFor258265($state, $op['source'] ?? null);
            $before = self::summary258265($state);

            if ($op['kind'] === 'claim') {
                $snapshot = self::token258265((string) ($op['snapshot'] ?? ''), 'snapshot name');
                $ack = self::token258265((string) ($op['ack'] ?? ''), 'reuse acknowledgement');
                $claim = self::token258265((string) ($op['claim'] ?? $snapshot . '-claim'), 'reuse claim');
                $events[] = self::claim258265($state, $source, $snapshot, $ack, $claim, $before);
                continue;
            }

            if ($op['kind'] === 'publish') {
                $snapshot = self::token258265((string) ($op['snapshot'] ?? ''), 'snapshot name');
                $claim = self::token258265((string) ($op['claim'] ?? ''), 'reuse claim');
                $token = self::token258265((string) ($op['token'] ?? 'publish'), 'publish token');
                $events[] = self::publish258265($state, $source, $snapshot, $claim, $token, $before);
