            return self::event258265('claim', 'missing-source-or-snapshot', $source, $before, self::summary258265($state), [
                'snapshot' => $snapshot,
                'ack' => $ack,
                'claim' => $claim,
            ]);
        }

        $sourceState = $state['sources'][$source];
        $snapshotState = $state['snapshots'][$snapshot];
        $blockers = self::reuseBlockers258265($snapshotState, $sourceState);
        $ackState = self::lastReuseAck258265($sourceState, $snapshot);
        if ($ackState === null || $ackState['receipt'] !== $ack) {
            $blockers[] = 'missing-reuse-ack';
        } elseif (
            $ackState['data_version'] !== $sourceState['data_version']
            || $ackState['published_count'] !== $snapshotState['published_count']
            || $ackState['receipt_digest'] !== $snapshotState['receipt_digest']
        ) {
            $blockers[] = 'stale-reuse-ack';
        }

        if ($blockers === []) {
            $state['sources'][$source]['reuse_claims'][] = [
                'token' => $claim,
                'snapshot' => $snapshot,
                'ack' => $ack,
                'data_version' => $sourceState['data_version'],
                'published_count' => count($sourceState['published']),
                'receipt_digest' => self::receiptDigest258265($sourceState['published']),
            ];
        }

        return self::event258265('claim', $blockers === [] ? 'claimed-reusable-current-source' : 'blocked-stale', $source, $before, self::summary258265($state), [
            'snapshot' => $snapshot,
            'ack' => $ack,
            'claim' => $claim,
            'reuse_claim_count' => count($state['sources'][$source]['reuse_claims'] ?? []),
            'blocked_reasons' => $blockers,
        ]);
