                'dirty_pages' => self::receiptList258265($source['dirty_pages'] ?? []),
                'published' => self::receiptMetadataList258265($source['published'] ?? []),
                'reuse_acks' => self::reuseAckList258265($source['reuse_acks'] ?? []),
                'reuse_claims' => self::reuseClaimList258265($source['reuse_claims'] ?? []),
