        foreach (is_array($current['snapshots'] ?? null) ? $current['snapshots'] : [] as $name => $snapshot) {
            if (!is_array($snapshot)) {
                continue;
            }
            $state['snapshots'][self::token258265((string) $name, 'snapshot name')] = [
                'source' => self::token258265((string) ($snapshot['source'] ?? 'main'), 'snapshot source'),
                'handle' => self::token258265((string) ($snapshot['handle'] ?? $name), 'snapshot handle'),
                'path' => self::path258265((string) ($snapshot['path'] ?? '')),
                'owner' => self::path258265((string) ($snapshot['owner'] ?? $snapshot['path'] ?? '')),
                'data_version' => self::nonNegativeInt258265($snapshot['data_version'] ?? 0, 'snapshot data version'),
                'published_count' => self::nonNegativeInt258265($snapshot['published_count'] ?? 0, 'snapshot published count'),
                'receipt_digest' => self::token258265((string) ($snapshot['receipt_digest'] ?? 'empty'), 'receipt digest'),
